/**
 * AgentStack transport: the room log lives in a StackScript generated by `generateRoomScript`
 * (exports `<id>.room.join|append|poll`, `<id>.lobby.find`). Calls go through the SDK's
 * StackScript client — no raw fetch here:
 *
 * ```ts
 * const runner = sdk.stackscript(projectId, { hostedMcp: true });   // players (cookie MCP); AgentStackSDK from @agentstack/sdk
 * const transport = stackscriptTransport(runner, { scriptId: 'tribute-room', exportPrefix: 'tribute' });
 * ```
 */
import type { QueueApi } from '../matchmaking.js';
import { errorKind, NetplayError } from '../errors.js';
import type { Body, Entry, Transport } from '../types.js';
import { pollingTransport, type PollingOptions, type RoomApi } from './polling.js';

/** Structural subset of the client returned by `sdk.stackscript(projectId, opts)` in @agentstack/sdk. */
export interface ScriptRunner {
  run(params: { script_id: string; export: string; input?: Record<string, unknown> | unknown[]; idempotency_key?: string; version?: string }): Promise<unknown>;
}

export interface StackscriptRoomOptions extends PollingOptions {
  scriptId: string;
  /** Export prefix used by the generator (defaults to the game id passed to generateRoomScript). */
  exportPrefix: string;
  /** 'live' (default) or a pinned version / 'staging'. */
  version?: string;
  /** `RETRY` (the room doc changed under our CAS: another player appended at the same moment) is repeated this many times. Default 4. */
  conflictRetries?: number;
  /** Base of the jittered backoff between conflict retries (ms): attempt n waits base·2^n · (0.5…1.5). Default 25. */
  conflictBackoffMs?: number;
  /** Test hook: wait `ms` (default setTimeout). */
  sleep?: (ms: number) => Promise<void>;
  /** Test hook: random in [0, 1) for the jitter (default Math.random). */
  random?: () => number;
}

/** Jittered backoff before conflict retry `attempt` (0-based): base·2^attempt scaled by 0.5…1.5, so clashing clients spread out. */
export function conflictDelayMs(attempt: number, baseMs: number, rnd: number): number {
  return Math.round(baseMs * 2 ** Math.min(attempt, 5) * (0.5 + rnd));
}

/** Same unwrap rules as `getStackscriptRunValue` in @agentstack/sdk (value | data.value | the object). */
export function runValue(payload: unknown): unknown {
  if (!payload || typeof payload !== 'object') return payload;
  const p = payload as Record<string, unknown>;
  if ('value' in p) return p.value;
  const d = p.data as Record<string, unknown> | undefined;
  if (d && typeof d === 'object' && 'value' in d) return d.value;
  return payload;
}

function check(v: unknown, what: string): Record<string, unknown> {
  const r = runValue(v) as Record<string, unknown> | null;
  if (!r || typeof r !== 'object') throw new Error(`netplay: ${what} returned no value`);
  if (typeof r.error === 'string') throw new NetplayError(errorKind(r.error), r.error, `netplay: ${what}`);
  return r;
}

const toEntries = (r: Record<string, unknown>): Entry[] =>
  (Array.isArray(r.entries) ? (r.entries as Record<string, unknown>[]) : []).map((e): Entry => ({
    seq: Number(e.seq), from: String(e.from), t: Number(e.t),
    body: (typeof e.body === 'string' ? JSON.parse(e.body) : e.body) as Body,
    ...(e.to ? { to: String(e.to) } : {}),
  }));

export function stackscriptRoomApi(runner: ScriptRunner, o: StackscriptRoomOptions): RoomApi & QueueApi {
  const retries = Math.max(0, o.conflictRetries ?? 4);
  const base = Math.max(0, o.conflictBackoffMs ?? 25);
  const sleep = o.sleep ?? ((ms: number) => new Promise<void>((r) => setTimeout(r, ms)));
  const rnd = o.random ?? Math.random;
  const call = async (name: string, input: Record<string, unknown>, key?: string): Promise<Record<string, unknown>> => {
    for (let attempt = 0; ; attempt++) {
      try {
        // a fresh idempotency key per attempt: RETRY means nothing was committed, and a platform that caches
        // replies by key must not hand the same RETRY back for the repeat
        const k = key ? (attempt ? `${key}~r${attempt}` : key) : undefined;
        return check(await runner.run({ script_id: o.scriptId, export: `${o.exportPrefix}.${name}`, input, version: o.version ?? 'live', ...(k ? { idempotency_key: k } : {}) }), name);
      } catch (err) {
        // RETRY = the room doc changed under our CAS (another player appended at the same moment): safe to repeat after a jittered pause
        if (!(err instanceof NetplayError && err.code === 'RETRY') || attempt >= retries) throw err;
        await sleep(conflictDelayMs(attempt, base, rnd()));
      }
    }
  };
  let self = '';
  let n = 0;
  const nonce = Math.floor(Math.random() * 1e9).toString(36);
  return {
    privateEntries: true,
    kind: 'stackscript',
    async join(room) {
      const r = await call('room.join', { room });
      self = String(r.self ?? '');
      if (!self) throw new NetplayError('auth', 'no_identity', 'netplay: room.join gave no identity (sign-in required)');
      return { self };
    },
    async append(room, body, to) {
      await call('room.append', { room, body: JSON.stringify(body), to: to ?? '' }, `${room}:${self}:${nonce}:${++n}`);
    },
    // up to 16 entries + read in one call (generated scripts accept `items` and `after`)
    async appendRead(room, items, afterSeq) {
      const list = items.map((it) => ({ body: JSON.stringify(it.body), to: it.to ?? '' }));
      return toEntries(await call('room.append', { room, items: list, after: afterSeq }, `${room}:${self}:${nonce}:${++n}`));
    },
    async poll(room, afterSeq) {
      return toEntries(await call('room.poll', { room, after: afterSeq }));
    },
    async find(game, seats) {
      const r = await call('lobby.find', { game, seats });
      return { room: String(r.room), seatsTaken: Number(r.seatsTaken ?? 0) };
    },
  };
}

/** Defaults for the hosted room: inputs batched every 100 ms, entries piggybacked on appends, poll 400 ms stretching to 2 s in a quiet room (presence beats and hash checks do not count as activity). */
export function stackscriptTransport(runner: ScriptRunner, o: StackscriptRoomOptions): Transport {
  return pollingTransport(stackscriptRoomApi(runner, o), { sendEveryMs: 100, idleMaxMs: 2000, ...o });
}
